use tcl_syntax::naming::{unroot_rooted_key, unroot_rooted_key_bytes};
fn main() {
    for (input, expected) in [("::", Some("")), (":::::p", Some(":::p")), ("::é\0雪", Some("é\0雪")), ("relative", None), (":x", None), ("", None)] {
        assert_eq!(unroot_rooted_key(input), expected, "text {input:?}");
        assert_eq!(unroot_rooted_key_bytes(input.as_bytes()), expected.map(str::as_bytes), "bytes {input:?}");
    }
    assert_eq!(unroot_rooted_key_bytes(b"::\xff\0:"), Some(&b"\xff\0:"[..]));
    assert_eq!(unroot_rooted_key_bytes(b"\xff::x"), None);
    println!("PASS registry-unroot: 6 text/byte pairs and 2 opaque-byte cases");
}
